G=load()

def components(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; cells=[]
                while st:
                    a,b=st.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==c and not seen[na][nb]: st.append((na,nb))
                out.append((c,cells))
    return out

def is_rect(cells):
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    bnd={(r,c) for r in (r0,r1) for c in range(c0,c1+1)} | {(r,c) for c in (c0,c1) for r in range(r0,r1+1)}
    return set(cells)==bnd

def transform(g):
    H,W=len(g),len(g[0]); out=[[0]*W for _ in range(H)]
    comps=components(g)
    rects=[]; others=[]
    for c,cells in comps:
        rs=[r for r,_ in cells]; cs=[c for _,c in cells]
        r0,c0=min(rs),min(cs); h=max(rs)-r0+1; w=max(cs)-c0+1
        pat=[[(1 if (r0+a,c0+b) in set(cells) else 0) for b in range(w)] for a in range(h)]
        (rects if is_rect(cells) else others).append((r0,c0,h,w,pat))
    # order by input position (top row, then col)
    key=lambda s:(s[0],s[1])
    rects.sort(key=key); others.sort(key=key)
    def place(shapes, top):
        occ=[[False]*W for _ in range(H)]
        for r0,c0,h,w,pat in shapes:
            def fits(r):
                for a in range(h):
                    for b in range(w):
                        if pat[a][b] and (r+a<0 or r+a>=H or occ[r+a][c0+b]): return False
                return True
            r = 0 if top else H-h
            step = 1 if top else -1
            while not fits(r): r+=step
            for a in range(h):
                for b in range(w):
                    if pat[a][b]: out[r+a][c0+b]=1; occ[r+a][c0+b]=True
    # need original colors; store color too
    return out

