def transform(g):
    H,W=len(g),len(g[0]); out=[[0]*W for _ in range(H)]
    rects=[]; others=[]
    for c,cells in components(g):
        S=set(cells); rs=[r for r,_ in cells]; cs=[c for _,c in cells]
        r0,c0=min(rs),min(cs); h=max(rs)-r0+1; w=max(cs)-c0+1
        pat=[[(1 if (r0+a,c0+b) in S else 0) for b in range(w)] for a in range(h)]
        item=(r0,c0,h,w,pat,c)
        (rects if is_rect(cells) else others).append(item)
    rects.sort(key=lambda s:(s[0],s[1])); others.sort(key=lambda s:(s[0],s[1]))
    def place(shapes, top):
        occ=[[False]*W for _ in range(H)]
        for r0,c0,h,w,pat,c in shapes:
            def fits(r):
                return all(not pat[a][b] or (0<=r+a<H and not occ[r+a][c0+b]) for a in range(h) for b in range(w))
            r=0 if top else H-h; step=1 if top else -1
            while not fits(r): r+=step
            for a in range(h):
                for b in range(w):
                    if pat[a][b]: out[r+a][c0+b]=c; occ[r+a][c0+b]=True
    place(rects,True); place(others,False)
    return out

